def _fmt_macs(v: float) -> str:  # MACs value to format
    """Format MACs with appropriate M/K suffix."""
    if v >= 1e6: return f"{v/1e6:8.2f} M"
    if v >= 1e3: return f"{v/1e3:8.2f} K"
